INSERT INTO public.points_of_interest (id, body_id, slug, name, type, lat, lon, history_text, dimensions, particle_config, sources, is_published) VALUES ('mars-olympus-mons', 'mars', 'olympus-mons', 'Olympus Mons', 'gunung'::public.poi_type, 18.65, 226.2, 'Olympus Mons adalah gunung berapi perisai raksasa di Mars yang merupakan gunung tertinggi di Tata Surya. Terbentuk dari ribuan aliran lava basaltik selama ratusan juta tahun di kerak Mars yang stasioner tanpa lempeng tektonik aktif.', '[{"label":"Tinggi dari datum","nilai":21.9,"satuan":"km","sumber":"NASA Mars Orbiter Laser Altimeter (MOLA)"},{"label":"Diameter dasar","nilai":600,"satuan":"km","sumber":"USGS Astrogeology Science Center"},{"label":"Kedalaman kaldera","nilai":3.2,"satuan":"km","sumber":"ESA Mars Express HRSC"},{"label":"Tinggi tebing pembatas","nilai":8,"satuan":"km","sumber":"NASA MRO HiRISE"}]'::jsonb, NULL, '["https://astrogeology.usgs.gov/search/map/Mars/Topography/OlympusMons_MOLA","NASA Mars Exploration Program (Olympus Mons Profile)","Smith et al. (2001) Mars Orbiter Laser Altimeter Experiment Results"]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET body_id = EXCLUDED.body_id, slug = EXCLUDED.slug, name = EXCLUDED.name, type = EXCLUDED.type, lat = EXCLUDED.lat, lon = EXCLUDED.lon, history_text = EXCLUDED.history_text, dimensions = EXCLUDED.dimensions, particle_config = EXCLUDED.particle_config, sources = EXCLUDED.sources, is_published = EXCLUDED.is_published, updated_at = now();
INSERT INTO public.points_of_interest (id, body_id, slug, name, type, lat, lon, history_text, dimensions, particle_config, sources, is_published) VALUES ('jupiter-great-red-spot', 'jupiter', 'great-red-spot', 'Badai Merah Raksasa', 'badai'::public.poi_type, -22, 270, 'Badai Merah Raksasa adalah pusaran antisiklonik bertekanan tinggi yang berputar berlawanan arah jarum jam di belahan selatan Jupiter. Telah diamati terus-menerus selama lebih dari 150 tahun dan didukung oleh dinamika atmosfer fluida tanpa hambatan gesekan permukaan padat.', '[{"label":"Panjang Timur-Barat","nilai":16350,"satuan":"km","sumber":"NASA Juno Mission Science Team (2021)"},{"label":"Lebar Utara-Selatan","nilai":10000,"satuan":"km","sumber":"Hubble Space Telescope OPAL Program"},{"label":"Kecepatan angin tepi","nilai":432,"satuan":"km/jam","sumber":"NASA Juno Microwave Radiometer (MWR)"},{"label":"Kedalaman akar badai","nilai":300,"satuan":"km","sumber":"Juno Gravity & MWR Joint Measurement (NASA 2021)"}]'::jsonb, '{"type":"badai_antisiklonik","count":40000,"speed":1.2,"vortexRadius":0.32,"color":"#d9381e","secondaryColor":"#e67332","coreColor":"#f6e2c3","direction":"counterclockwise"}'::jsonb, '["https://science.nasa.gov/mission/juno/great-red-spot/","Bolton et al. (2021) Science: Microwave Observations of Jupiter’s Atmosphere and Great Red Spot","NASA JPL Solar System Dynamics"]'::jsonb, true) ON CONFLICT (id) DO UPDATE SET body_id = EXCLUDED.body_id, slug = EXCLUDED.slug, name = EXCLUDED.name, type = EXCLUDED.type, lat = EXCLUDED.lat, lon = EXCLUDED.lon, history_text = EXCLUDED.history_text, dimensions = EXCLUDED.dimensions, particle_config = EXCLUDED.particle_config, sources = EXCLUDED.sources, is_published = EXCLUDED.is_published, updated_at = now();
