INSERT INTO public.quizzes (id, poi_id, title, description, is_published) VALUES ('a1b2c3d4-e5f6-47a8-b9c0-112233445566', 'mars-olympus-mons', 'Kuis Geologi Olympus Mons', 'Uji pemahamanmu tentang gunung api perisai terbesar di Tata Surya.', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_option_id, explanation, sort_order) VALUES ('a1b2c3d4-e5f6-47a8-b9c0-112233445566', 'Mengapa Olympus Mons bisa tumbuh hingga ketinggian lebih dari 21 km dibanding gunung di Bumi?', '[{"id":"a","text":"Karena Mars tidak memiliki lempeng tektonik yang bergerak"},{"id":"b","text":"Karena gravitasi Mars lebih kuat dari Bumi"},{"id":"c","text":"Karena atmosfer Mars tersusun dari lava"},{"id":"d","text":"Karena tumbukan komet raksasa"}]'::jsonb, 'a', 'Tanpa lempeng tektonik aktif di Mars, kerak tetap diam di atas titik panas magma, sehingga letusan lava basaltik terus bertumpuk di lokasi yang sama selama ratusan juta tahun.', 1), ('a1b2c3d4-e5f6-47a8-b9c0-112233445566', 'Berapa perkiraan rata-rata kemiringan lereng gunung Olympus Mons?', '[{"id":"a","text":"Sekitar 45 derajat"},{"id":"b","text":"Sekitar 5 derajat (sangat landai)"},{"id":"c","text":"Sekitar 80 derajat"},{"id":"d","text":"Sekitar 25 derajat"}]'::jsonb, 'b', 'Sebagai gunung berapi perisai (shield volcano), lelehan lava basal yang encer membentuk lereng yang sangat luas dan landai dengan sudut rata-rata hanya ~5 derajat.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public.quizzes (id, poi_id, title, description, is_published) VALUES ('b2c3d4e5-f6a7-48b9-c0d1-223344556677', 'jupiter-great-red-spot', 'Kuis Atmosfer Badai Merah Raksasa', 'Uji pengetahuanmu tentang pusaran antisiklonik raksasa Jupiter.', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_option_id, explanation, sort_order) VALUES ('b2c3d4e5-f6a7-48b9-c0d1-223344556677', 'Ke arah mana pusaran Badai Merah Raksasa berputar sebagaimana diamati dari belahan selatan Jupiter?', '[{"id":"a","text":"Searah jarum jam"},{"id":"b","text":"Berlawanan arah jarum jam (antisiklonik)"},{"id":"c","text":"Tegak lurus terhadap kutub"},{"id":"d","text":"Tidak berputar"}]'::jsonb, 'b', 'Badai Merah Raksasa adalah antisiklon bertekanan tinggi di belahan bumi selatan Jupiter, sehingga gaya Coriolis menyebabkannya berputar berlawanan arah jarum jam.', 1) ON CONFLICT DO NOTHING;
